const TOTAL = 4000;
const DRAW_MS = 1800;
const FILL_START = 1600;
const FILL_MS = 600;

/** ストローク描画〜塗り完了まで（`tick` が止まるまで）。スプラッシュ後に本画面を開く待ち時間に使う */
export const FITLOOK_LOGO_SPLASH_DURATION_MS = DRAW_MS + FILL_MS;

function ease(t: number): number {
  return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
}

/**
 * `logo.html` と同じストローク描画 → 塗りフェード。戻り値で rAF を停止。
 */
export function mountFitLookLogoLoadingAnimation(container: HTMLElement): () => void {
  const wrap = document.createElement("div");
  wrap.style.cssText =
    "display:flex;align-items:center;justify-content:center;width:100%;padding:24px;box-sizing:border-box;";
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", "0 0 294 268");
  svg.setAttribute("fill", "none");
  svg.setAttribute("xmlns", "http://www.w3.org/2000/svg");
  svg.style.cssText = "width:min(72vw, 220px);height:auto;max-height:38vh;display:block;";
  const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
  path.setAttribute("d", FITLOOK_LOGO_SVG_PATH_D);
  path.setAttribute("stroke", "#111");
  path.setAttribute("stroke-width", "1");
  path.setAttribute("fill", "transparent");
  svg.appendChild(path);
  wrap.appendChild(svg);
  container.appendChild(wrap);

  let raf: number | null = null;
  let startTime: number | null = null;

  function reset(): void {
    path.style.strokeDasharray = String(TOTAL);
    path.style.strokeDashoffset = String(TOTAL);
    path.style.fill = "transparent";
  }

  function tick(ts: number): void {
    if (startTime == null) startTime = ts;
    const e = ts - startTime;
    path.style.strokeDashoffset = String(TOTAL * (1 - ease(Math.min(e / DRAW_MS, 1))));
    if (e >= FILL_START) {
      path.style.fill = `rgba(0,0,0,${ease(Math.min((e - FILL_START) / FILL_MS, 1))})`;
    }
    if (e < DRAW_MS + FILL_MS) raf = requestAnimationFrame(tick);
    else raf = null;
  }

  function play(): void {
    if (raf != null) cancelAnimationFrame(raf);
    raf = null;
    reset();
    requestAnimationFrame(() => {
      startTime = null;
      raf = requestAnimationFrame(tick);
    });
  }

  play();

  return () => {
    if (raf != null) cancelAnimationFrame(raf);
    raf = null;
  };
}
